parameters.jsCode:
const raw = $json.text;

const cleaned = JSON.parse(raw);

return [{
json:{
 intent: cleaned.intent,
 symptom: cleaned.symptom,
 date: cleaned.date,
 patient_name: cleaned.patient_name
}
}];

const date = $json.date;

let slots = [];

if(date==="today"){
  slots = [
    "11:00 AM",
    "1:30 PM",
    "4:00 PM"
  ];
}
else{
  slots = [
    "10:00 AM",
    "12:00 PM",
    "5:00 PM"
  ];
}

return [{
json:{
...$json,
available_slots: slots
}
}];

const name = $json.patient_name || "Patient";
const slots = $json.available_slots;

const reply =
`${name} ji, available appointment slots:

${slots.join("\n")}

Reply with preferred slot.`;

return [{
  ...$json,
  reply
}];

const name = $json.patient_name;
const slot = $json.selected_slot;

return [{
json:{
...$json,
confirmation:
`${name} ji, your appointment is confirmed for ${slot}.

Please arrive 10 minutes early.`
}
}];

// Grab the raw response coming from the Gemini chain
const raw = $json.text || $json.output || $input.first().json.text;

// Parse the text into a clean data object
const cleaned = JSON.parse(raw);

// Pass everything downstream directly to our upcoming routing gates
return [
  {
    patient_name: cleaned.patient_name || null,
    symptom: cleaned.symptom || null,
    selected_slot: cleaned.selected_slot || null,
    confidence_score: parseInt(cleaned.confidence_score) || 0,
    emergency_flag: cleaned.emergency_flag === true || cleaned.emergency_flag === "true"
  }
];

// 1. Define the clinic's standard template slots
const masterSlots = [
  "10:00 AM",
  "10:30 AM",
  "11:00 AM",
  "11:30 AM",
  "12:00 PM",
  "12:30 PM",
  "1:00 PM",
  "1:30 PM",
  "2:00 PM"
];

// 2. Fetch current time metrics to eliminate past slots
const now = new Date();
const currentMinutesFromMidnight = (now.getHours() * 60) + now.getMinutes();

// Helper function to turn a time string (like "10:30 AM") into minutes from midnight
function timeToMinutes(timeStr) {
  const [time, modifier] = timeStr.split(' ');
  let [hours, minutes] = time.split(':').map(Number);
  if (hours === 12) {
    hours = modifier === 'AM' ? 0 : 12;
  } else if (modifier === 'PM') {
    hours += 12;
  }
  return (hours * 60) + minutes;
}

// 3. Fetch busy events from Google Calendar
let busyEvents = [];
try {
  busyEvents = $items("Get availability in a calendar").map(item => item.json);
} catch (e) {
  busyEvents = [];
}

// 4. Filter the slots based on BOTH calendar blocks and the current time
const availableSlots = masterSlots.filter(slot => {
  const slotStart = timeToMinutes(slot);
  const slotEnd = slotStart + 30;

  // RULE A: If the slot has already passed today, drop it immediately!
  if (slotStart <= currentMinutesFromMidnight) {
    return false;
  }

  // RULE B: Check for collision blocks against Google Calendar events
  for (const event of busyEvents) {
    if (!event.start || !event.end) continue;

    const eventStartDate = new Date(event.start);
    const eventEndDate = new Date(event.end);

    const eventStart = (eventStartDate.getHours() * 60) + eventStartDate.getMinutes();
    const eventEnd = (eventEndDate.getHours() * 60) + eventEndDate.getMinutes();

    if (slotStart < eventEnd && slotEnd > eventStart) {
      return false; // Slot overlaps with a calendar block
    }
  }
  return true; // Slot is completely free and in the future
});

// 5. Extract the top 3 upcoming valid slots
const finalSuggestions = availableSlots.slice(0, 3);

return [{
  json: {
    ...$input.first().json,
    suggested_slots: finalSuggestions.length > 0 ? finalSuggestions : ["No more slots available today"]
  }
}];

const name = $input.first().json.patient_name || "Patient";
const available = $input.first().json.available;

let reply="";

if (available===true){
 reply=`${name} ji, appointment slot available hai. Reply YES to confirm booking.`;
}else{
 reply=`${name} ji, doctor abhi busy hai. Main next slot suggest karta hu.`;
}

return [{
 json:{
   ...$input.first().json,
   reply
 }
}];

return [{
  json:{
    reply:"Please reply YES to confirm your appointment booking."
  }
}];

const name = $json.patient_name || $json.Name || "Patient";

const slot =
$json.selected_slot ||
$json.Slot ||
"assigned slot";

return [{
json:{
...$json,
final_message:
`${name} ji, your appointment has been successfully booked.

Slot: ${slot}

Please arrive 10 minutes early.
Thank you.`
}
}];

const name = $json.patient_name;

const slots = $json.suggested_slots.join(", ");

return [{
json:{
...$json,
reply:
`${name} ji, doctor abhi busy hain.

Available slots:
${slots}

Please select one.`
}
}];

return [{
json:{
reply:"This slot is already booked or an appointment already exists. Please choose another time."
}
}];

const now = Date.now();
const lastBooking = $json.last_booking_time || 0;

// 5 minute protection window
const blocked = (now - lastBooking) < (5 * 60 * 1000);

return [{
  json:{
    ...$json,
    booking_locked: blocked
  }
}];

return [{
json:{
reply:
"You recently booked an appointment. Please wait a few minutes before trying again."
}
}]

// Check if the LLM parsed a specific time slot, otherwise default to a safe working hour (e.g., 10 AM)
const slotText = $json.selected_slot ? $json.selected_slot.toLowerCase() : '';
let hour = new Date().getHours();

// Intelligent slot mapping so text times pass working hours checks
if (slotText.includes('11') || slotText.includes('morning') || slotText.includes('10')) {
  hour = 10; // Sets it perfectly inside the 9 AM - 1 PM working window
} else if (slotText.includes('7') || slotText.includes('evening') || slotText.includes('6')) {
  hour = 18; // Sets it perfectly inside the 5 PM - 8 PM working window
}

// Global Override for Live Testing: If you are actively debugging, force it to pass
const isTesting = true; 

if (isTesting) {
  return [{
    json: {
      ...$json,
      clinic_open: true,
      reason: "Test mode override: Passed timing validations."
    }
  }];
}

// --- Standard Production Guardrails ---
const day = new Date().getDay();

// Sunday closed
if (day === 0) {
  return [{
    json: {
      ...$json,
      clinic_open: false,
      reason: "Clinic is closed today."
    }
  }];
}

// Working hours check
if (!((hour >= 9 && hour < 13) || (hour >= 17 && hour < 20))) {
  return [{
    json: {
      ...$json,
      clinic_open: false,
      reason: "Outside clinic working hours."
    }
  }];
}

return [{
  json: {
    ...$json,
    clinic_open: true
  }
}];

return [{
  json: {
    reply: "Hello! Thank you for reaching out to Clinicos. Our team is currently away (Clinic Hours are Monday to Saturday, 9:00 AM to 8:00 PM).\n\nWe have safely received your request and your preferred slot details! Our front desk executive will verify the calendar and text you a formal confirmation first thing tomorrow morning. Have a restful night!"
  }
}];

const name = $json.Name;
const slot = $json.Slot;

return {
  json: {
    ...$json,

    message:
`Reminder:

${name} ji,

You have an appointment today at ${slot}.

Please arrive 10 minutes early.`
  }
};

